/* story-form-19 — Day10 ledger tray winner; headphones yields */
body.rp-ledger-wins .rp-stage-prop--headphones-note,
body.rp-ledger-wins [data-testid="story-street-headphones-note"],
body[data-day-index="10"] .rp-stage-prop--headphones-note,
body[data-day-index="11"] .rp-stage-prop--headphones-note,
body[data-day-index="12"] .rp-stage-prop--headphones-note {
  display: none !important;
}
.rp-stage-prop--ledger-tray-winner {
  left: 16%; width: 42%; top: 54%; height: 24%;
  z-index: 10;
  color: #e8c9a0;
  animation: rp-ledger-win 1.8s ease-in-out infinite;
}
.rp-stage-prop--ledger-tray-winner .rp-stage-prop__tag {
  font-size: 12px;
  background: rgba(12,8,6,.92);
  border: 1px solid rgba(232,180,120,.55);
}
.rp-ledger-svg { width: 100%; height: 100%; display: block; }
@keyframes rp-ledger-win {
  0%, 100% { filter: drop-shadow(0 0 0 rgba(232,180,120,0)); }
  50% { filter: drop-shadow(0 0 8px rgba(232,180,120,.35)); }
}
.rp-recommend-tonight-bar[data-candidate="true"] {
  border-color: rgba(232,180,120,.75);
  box-shadow: 0 0 0 1px rgba(232,180,120,.25);
  font-weight: 600;
}

