function storyForm19(){ return state.questPack?.storyForm19 || state.storyForm19 || null; }

function cleanLedgerTrayHtml() {
  const c = storyForm19()?.cleanLedgerTrayWinner;
  if (!c) return ledgerPropHtml(); // legacy
  return state.locale === "tr" && c.htmlTr ? c.htmlTr : c.html;
}

function ledgerPropHtml() {
  // Prefer form19 clean SVG always for tray testId
  const c = storyForm19()?.cleanLedgerTrayWinner;
  if (c) return state.locale === "tr" && c.htmlTr ? c.htmlTr : c.html;
  // ...prior packs...
}

function syncLedgerWinsBodyClass() {
  const day = state.save.dayIndex || 1;
  const wins = day >= 10 || storyFlag("natural_ledger_street_wins");
  document.body.classList.toggle("rp-ledger-wins", wins);
  if (wins) document.body.dataset.dayIndex = String(day);
}

function armRecommendTonightCandidate() {
  const f = state.save.storyFlags || (state.save.storyFlags = {});
  const rule = storyForm19()?.armRecommendTonightCandidate;
  if (!rule) return;
  // ensure tease accompanies lived beat
  if (f.decibel_lived_beat_done) {
    for (const k of rule.ensureLedgerTeaseOnLived?.setsFlags || []) f[k] = true;
  }
  const a = rule.armWhen?.flagsAll || [];
  const b = rule.alsoArmWhen?.flagsAll || [];
  const okA = a.length && a.every((k) => f[k]);
  const okB = b.length && b.every((k) => f[k]);
  if (okA || okB) {
    f[rule.setsFlag || "would_recommend_tonight_candidate"] = true;
  }
}

function recommendTonightBarHtml() {
  armRecommendTonightCandidate();
  const bar = storyForm19()?.armRecommendTonightCandidate?.bar
    || storyForm18()?.cultRecommendTonightBar?.recommendTonight;
  if (!bar) return "";
  const show = storyFlag("decibel_lived_beat_done") || storyFlag("quest_ledger_tease") || storyFlag("week2_decibel_ledger_seen") || (state.save.dayIndex||1) >= 7;
  if (!show) return "";
  const candidate = !!storyFlag("would_recommend_tonight_candidate");
  const copy = candidate
    ? (bar.copy || storyForm18()?.cultRecommendTonightBar?.recommendTonight?.copyWhenCandidate)
    : (storyForm18()?.cultRecommendTonightBar?.recommendTonight?.copyWhenClimbing);
  return `<div class="rp-recommend-tonight-bar" data-testid="recommend-tonight-bar" data-candidate="${candidate}">${loc(copy)}</div>`;
}

